   102|<header class="site-header">
   103|  <div class="nav-wrap">
   104|    <a href="/" class="logo">🐾 Haustier<span>zentrum</span></a>
   105|    <button class="nav-toggle" aria-label="Menü" onclick="document.querySelector('.main-nav').classList.toggle('open');this.textContent=this.textContent=='☰'?'✕':'☰'">☰</button>
